import{_ as a,H as t,f as i,i as s}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"31 | 多线程：RN底层是如何保障交互体验的？","description":"","frontmatter":{},"headers":[{"level":2,"title":"进程和线程","slug":"进程和线程","link":"#进程和线程","children":[]},{"level":2,"title":"React Native 中的多线程","slug":"react-native-中的多线程","link":"#react-native-中的多线程","children":[]},{"level":2,"title":"渲染与线程","slug":"渲染与线程","link":"#渲染与线程","children":[]},{"level":2,"title":"在主线程中渲染","slug":"在主线程中渲染","link":"#在主线程中渲染","children":[]},{"level":2,"title":"在背景线程中渲染","slug":"在背景线程中渲染","link":"#在背景线程中渲染","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"ReactNative新架构实战课/31｜多线程：RN底层是如何保障交互体验的？.md","filePath":"ReactNative新架构实战课/31｜多线程：RN底层是如何保障交互体验的？.md","lastUpdated":1795533704000}'),n={name:"ReactNative新架构实战课/31｜多线程：RN底层是如何保障交互体验的？.md"};function p(l,e,o,r,c,h){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="_31-多线程-rn底层是如何保障交互体验的" tabindex="-1">31 | 多线程：RN底层是如何保障交互体验的？ <a class="header-anchor" href="#_31-多线程-rn底层是如何保障交互体验的" aria-label="Permalink to &quot;31 | 多线程：RN底层是如何保障交互体验的？&quot;">​</a></h1><p>你好，我是蒋宏伟。</p><p>在上一讲中，我们主要介绍的是 JavaScript 引擎，而 React Native 的一大特点，就是为执行JavaScript 脚本单独开了一个异步线程。</p><p>和任何其他应用一样，React Native 应用也需要处理并行任务，比如，在用户滚动页面的时候，不仅要处理用户的滚动手势，并需要将页面绘制到新位置上，与此同时，还可能需要发起新的请求和做一些局部的渲染。只有单个线程时，处理任务就需要排队，前一个没完成，后一个就需要等待，这就容易导致交互的卡顿。</p><p>这一讲中，我们会围绕着 React Native 的多线程进行介绍，并会重点介绍新架构是如何改善交互体验的。</p><h2 id="进程和线程" tabindex="-1">进程和线程 <a class="header-anchor" href="#进程和线程" aria-label="Permalink to &quot;进程和线程&quot;">​</a></h2><p>任何 React Native 应用，都是一个多线程的应用，这是由其架构设计的特点所决定的。</p><p>应用、进程、线程这些计算机的概念，关联性很强，也容易弄混。明确这些概念，有利于我们去理解 React Native 的多线程架构，因此我们借用微软给出的关于应用、进程和线程的定义，来回忆一下这些熟悉的概念。</p><p>一个应用由一个或多个进程组成。一个进程，用最简单的话说，就是一个正在执行的程序，该程序的上下文中运行着一个或多个线程。一个线程是操作系统分配处理器时间的基本单位，一个线程可以执行进程代码的任何部分，包括目前正在被另一个线程执行的部分。</p><ul><li>An application consists of one or more processes. A process, in the simplest terms, is anexecuting program. One or more threads run in the context of the process. A thread is thebasic unit to which the operating system allocates processor time. A thread can executeany part of the process code, including parts currently being executed by another thread.</li></ul><p>首先，每个应用至少会有 1 个进程。</p><p>为了更好地理解上面的定义，咱们可以使用 Mac 系统自带的 Activity Monitor 工具，去查看相关应用到底有哪些进程。比如，下图是我在电脑中开的 Chrome 应用和 zsh 命令行应用：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/31/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/31/1.png" alt=""></a></p><p>我开启的 Chrome 应用它有 10 多个进程。包括一个命名为 Google Chrome 的进程，若干个crashpad_handler 进程和若干个 Helper 进程。这些 Helper 进程中，有的负责处理 GPU，有的负责处理 Renderer。也就是说，一个应用可由多个进程组成。</p><p>而对于 zsh 这样的工具类应用，它非常简单，一个应用就只由 1 个进程组成。</p><p>其次，每个进程至少会有 1 个线程。</p><p>咱们将注意力放在 Google Chrome 进程和 zsh 进程上：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/31/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/31/2.png" alt=""></a></p><p>Google Chrome 的进程它有 31 个线程，而 zsh 进程只有 1 个线程。</p><p>为什么 Chrome 浏览器它是多进程多线程的，而 zsh 命令行工具是单进程单线程的？因为二者要处理的任务的复杂度不同，特别是对并行任务的处理。</p><p>在计算机底层，线程是操作系统分配 CPU 时间的基本单元，同一个线程在同一个时间单元中，只能执行一个代码模块，这个代码模块代表的是某个具体的工作任务，比如计算 1+1，在该线程执行 1+1 的时候它不能同时去执行其他任务，比如同时发起请求。</p><p>如果要让应用在计算的同时处理多个任务，那怎么办呢？再另起一个线程。在同一时间内，不同的线程可以同时处理不同的任务。一个多线程的示意图如下所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/31/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/31/3.png" alt=""></a></p><p>当我们给计算机分配一个任务时，如果这个任务可被分解成若干个可独立执行子任务，那么这时可以在主线程中创建若干个线程，来分别处理这些子任务。从计算机底层视角看，一个计算机可能会有多个 CPU，而每个 CPU 又是可以开多个线程的，因此计算机是可以同时处理这些可独立执行的子任务的，这就是并行的原理。</p><p>那什么时候我们需要多线程多进程来处理并发任务呢？</p><p>这需要根据任务的复杂度来确定。任务的复杂度不一样，需要的进程和线程的数量也不一样。打个比方，在一个大型项目中，要多个不同职能团队紧密合作，而且每个职能团队又会配备多个人，这就类似于多进程多线程。在一个中型项目中，一个多人团队就能完成好，这就类似单进程多线程模型。而一个人就能搞定的小型项目，就类似于单进程单线程。</p><h2 id="react-native-中的多线程" tabindex="-1">React Native 中的多线程 <a class="header-anchor" href="#react-native-中的多线程" aria-label="Permalink to &quot;React Native 中的多线程&quot;">​</a></h2><p>而 React Native 框架底层，采用的是单进程多线程的设计。在 React Native 应用中至少会有三个线程：</p><ol><li><p>主线程（也叫做 UI 线程）</p></li><li><p>JavaScript 线程</p></li><li><p>Background 线程（也叫做 ShadowQueue 线程）</p></li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/31/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/31/4.png" alt=""></a></p><p>主线程是唯一一个可以操作视图的线程。React Native 应用本质是 iOS 应用或 Android 应用，因此，在启动时，操作系统也会为其创建唯一可操作视图的主线程。无论是 iOS 应用还是 Android 应用，在启动应用的时候，系统都会为该应用创建一个主线程，来负责用户交互和界面绘制，而除了主线程外，其他线程是不可以操作视图的。</p><p>JavaScript 线程是用于执行 JavaScript 脚本的线程。大多数情况下，JavaScript 脚本会交由JavaScript 引擎来执行，比如处理点击手势、拼接接口字段、发起请求和执行 React Render函数等任务。但值得注意的是，并不是任何的 JavaScript 脚本的执行都在 JavaScript 线程进行。</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">从源码中，可以看到 JavaScript 线程的名字叫做 com.facebook.react.JavaScript。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">static NSString </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> RCTJSThreadName</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> @</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;com.facebook.react.JavaScript&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>ShadowQueue 线程是用于布局的线程。React Native 应用的布局任务，会交由 Yoga 布局引擎来执行，而 Yoga 布局引擎的执行，大多数情况下，是在 ShadowQueue 线程执行的。</p><p>从源码中，可以看到 ShadowQueue 线程的名字叫做</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">com.facebook.react.ShadowQueue。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">char </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> RCTUIManagerQueueName</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;com.facebook.react.ShadowQueue&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>除了以上三大线程之外，React Native 还会开启另外一些线程用于任务的执行。在 ReactNative iOS 源码中，你可以找到下面这些单独创建的线程：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dispatch_queue_create(&quot;com.facebook.react.ModuleClassesSyncQueue&quot;, DISPATCH_QUEUE</span></span>
<span class="line"><span>dispatch_queue_create(&quot;com.facebook.react.WebSocketExecutor&quot;, DISPATCH_QUEUE_SERI</span></span>
<span class="line"><span>dispatch_queue_create(&quot;com.facebook.react.AsyncLocalStorageQueue&quot;, DISPATCH_QUEUE</span></span></code></pre></div><p>以上这些能够单独执行的三类任务，包括 Module 模块、WebSocket 长链接和 Storage 存储，每次调用相关模块的时候，React Native 都会为它们创建单独的线程。当然，还有 HTTP请求之类的任务，也都有单独的线程进行处理，就不一一列举了。</p><p>简而言之，一个 React Native 应用有三个核心线程，以及根据任务情况随时创建的独立线程。</p><h2 id="渲染与线程" tabindex="-1">渲染与线程 <a class="header-anchor" href="#渲染与线程" aria-label="Permalink to &quot;渲染与线程&quot;">​</a></h2><p>对于任何的 GUI 应用而言，保障渲染体验是其重中之重。而多线程机制正是保障 ReactNative 渲染体验的核心要素之一。</p><p>一般而言，在 React Native 中，一个渲染任务可分为 5 个子任务。比如，先处理点击手势（Event），接着执行 React Render 函数，之后 Yoga 引擎开始计算布局（Layout），再然后框架提交（Commit）为渲染而准备的 “React Shadow Tree”，最后将挂载（Mount）“ReactShadow Tree”，并在屏幕上显示。示意图如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/31/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/31/5.png" alt=""></a></p><p>从上述流程中，我们可以发现，渲染子任务之间的关系必须是串行的，它的后一个子任务必须等待前一个子任务执行完成后才能继续执行。</p><p>在介绍多线程时，我们提到过，只有当任务可被分解成若干个可独立执行子任务时，多线程才能并行地处理它们，从而提高任务整体执行的效率。虽然渲染任务能被分解成若干个子任务，但是这些子任务之间是有先后顺序和依赖关系的，并不能完全独立地执行，这就不满足多线程并行执行的要求。</p><p>那么，为什么 React Naitve 还要弄三个线程来处理渲染任务？要弄清楚这点，就必须得弄清楚 React Native 的线程模型了。</p><p>React Native 新架构的线程模型非常复杂，并不是简单的在三个核心线程之间异步地执行，而是根据不同场景采用不同的方案来执行渲染任务，官方文档中给出了 6 种场景下的 6 种渲染任务的执行方案。具体的方案，就不一一列举了，咱们只需握住核心：不同优先级的渲染任务用不一样的线程解决方案。</p><p>其中，最重要的两个场景方案是：</p><ol><li><p>在主线程中渲染：对于高优先级的渲染任务，它的所有子任务会同步地在主线程上执行。</p></li><li><p>在背景线程中渲染：对于一般场景的渲染任务，它的大部分子任务会在 JavaScript 线程和Background 线程中执行。</p></li></ol><ul><li>Render in the UI Thread：When there is a high priority event on the UI Thread, therenderer is able to execute all the render pipeline synchronously on the UI thread.Render in a Background Thread：This is the most common scenario where most of therender pipeline happens on JavaScript and background thread.</li></ul><h2 id="在主线程中渲染" tabindex="-1">在主线程中渲染 <a class="header-anchor" href="#在主线程中渲染" aria-label="Permalink to &quot;在主线程中渲染&quot;">​</a></h2><p>由于 iOS 和 Android 的更新 UI 机制的限制，非主线程一般是不能操作 UI 的，加之多线程本身也会增加复杂度，因此，只在主线程中渲染的流程最简单，因此，我们先讨论它。</p><p>有些同学可能会怀疑，只有主线程，会不会导致 React Native 的卡顿。这种担心是不无道理的，因为，对于纯 Native 应用而言，它可以直接操作 UI，而 React Native 应用还需要额外考虑 JavaScript 执行的时间，这就更可能会导致卡顿。</p><p>但可能会卡顿并不等同于一定会卡顿。有些高优先级的渲染任务，就非常适合只在主线程中执行。根据渲染原理可知，若在 1s 之内能够稳定地渲染出 60 帧，也就是 16ms 每帧，那么渲染就是流畅的；只有超过 16ms，用户才可能会觉得卡顿。换句话说，在单次渲染任务中，只要 JavaScript 执行和 UI 操作的总耗时不超过 16ms，那么，用户就不会感觉卡顿。</p><p>例如，在《07｜TextInput：如何实现一个体验好的输入框？》 中提到的 TextInput，它就有个“隐藏”事件，可以触发这种高优先级的同步渲染任务。</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;​TextInput</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> unstable_onChangeSync={event =&gt; {}​}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/&gt;</span></span></code></pre></div><p>此时，用户输入文字触发的回调方法，以及后续的其他的渲染子任务，都会在主线程中执行。在主线程中渲染的示意图如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/31/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/31/6.png" alt=""></a></p><p>主线程执行的 5 个任务依次是，先执行关于文字输入事件（Event）的回调函数，若回调函数触发了 setState 方法后，就会接着执行 React 的 “Render” 方法，然后在计算具体的元素布局（Layout），再然后框架提交（Commit）为渲染而准备的 “React Shadow Tree”，最后将挂载（Mount）“React Shadow Tree”，并在屏幕上显示。</p><p>当然，官方也提示了这种高优先级的同步渲染的风险性：unstable_onChangeSync 回调将会在主线程中执行，并且它可能会导致掉帧。</p><ul><li>Callback will be called on the main thread and may result in dropped frames.</li></ul><h2 id="在背景线程中渲染" tabindex="-1">在背景线程中渲染 <a class="header-anchor" href="#在背景线程中渲染" aria-label="Permalink to &quot;在背景线程中渲染&quot;">​</a></h2><p>然而，正如我们前面提到的，React Native 应用相对于 Native 应用而言，多了 JavaScript 执行这一步，这就增加了渲染任务不能在 16ms 内执行完成的风险。因此，在大部分情况下，开发者只需使用 TextInput 组件的 onChange 回调来更新页面即可。</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;​TextInput</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> onChange={event =&gt; {}​}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/&gt;</span></span></code></pre></div><p>和其他组件方法一样，TextInput 组件的 onChange 方法是多线程异步执行的，这种机制就叫做在背景线程中渲染。其示意图如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/31/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ReactNative%E6%96%B0%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/31/7.png" alt=""></a></p><p>该渲染任务依旧可分为 5 个子任务，Event、Render、Layout、Commit 和 Mount，并且这些子任务也需要依次执行。但和只在主线中渲染的方案不同，该方案极大地降低了主线程卡顿的问题，因为 Event 和 Render 相关的 JavaScript 代码是在 JavaScript 线程中执行的，而Layout、Commit 是在背景线程中执行的。</p><p>由于主线程、JavaScript 线程和 Background 线程是三个相互独立的线程，因此它们可以并行地执行任务，并且不相互干扰。例如，在执行前四个子任务（Event、Render、Layout、Commit）时，主线程是空闲的状态，这时，主线程可以并行地处理类似于用户滚动之类的交互任务。这就意味着，即便前四个子任务中的耗时超过了 16ms，但只要主线程的 Mount 子任务不超过 16ms，用户也感觉不到卡顿。这就是，在背景线程中渲染方法的优势。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>总而言之，React Native 新架构在底层会创建至少三个线程。框架默认采用三线程异步渲染，对于高优先级的渲染任务可采用同步渲染。</p><p>三线程异步渲染的优势在于，即便 JavaScript 任务执行时间过长，但主线程依旧可以同时响应用户的操作。例如，极端情况下 JavaScript 假死，页面依旧可以滑动。根据实践经验，大部分的卡顿确实是 JavaScript 中的任务执行耗时长导致的。</p><p>此外，某些特定场景下，提高交互事件优先级，使用主线程同步渲染，也是一种保障交互体验的手段。例如，在用户输入 TextInput 文字，并有大范围渲染页面的场景下，提高用户输入文字的优先级，可减少渲染导致的输入文字卡顿问题。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>请你想想，React Native 是否可以设计成只使用 JavaScript 线程和主线程的“双线程”异步渲染模型呢？三线程异步渲染，相对于“双线程”的优势在哪？</p><p>欢迎在留言区分享你的经验、交流学习心得或者提出问题，如果觉得有收获，也期待你把今天的内容分享给更多的朋友！</p>`,76)])])}const d=a(n,[["render",p]]);export{u as __pageData,d as default};
